    public static List<List<Integer>> solution(int[] arr) {

        Arrays.sort(arr);
        Arrays.stream(arr).forEach( x -> System.out.print(" "+x));

        System.out.println();

        List<List<Integer>> fSolution=new ArrayList< List<Integer> >();
        Set<List<Integer>> seen = new HashSet<>();

        if(arr.length >=1 )
            for(int i=0;i<arr.length-1;i++)
            {
                int k=i+1;
                int l= arr.length-1;
                do {

                    if(i==k && k==l)
                    {
                        
                    }
                        if( k==l)
                        break;

                    while( i != k-1 && k < arr.length-1 && arr[k] == arr[k+1])
                        k++;

                    while( l < arr.length-1 &&  arr[l] == arr[l-1] && l > 1)
                        l--;

                    int target=-(arr[i]);
                    int sum=arr[k]+arr[l];

                    if(sum < target )
                    {k++;continue;}

                    if(sum > target)
                    {l--;;continue;}

                    if(sum == target)
                    {

                        int x = arr[i], y = arr[k], z = arr[l];

                        if (x > y) { int t = x; x = y; y = t; }
                        if (x > z) { int t = x; x = z; z = t; }
                        if (y > z) { int t = y; y = z; z = t; }

                        List<Integer> tri = List.of(x, y, z);   // immutable but fine — we only read/hash it
                        if (seen.add(tri)) fSolution.add(tri);
                        k++;
                        l--;
                    }

                }while( k<arr.length-1 && l > 0);

            }
        return fSolution;

    }
